/* ==UserStyle==
@name         Nitro Type Race Prompt — Larger Font
@namespace    userstyles
@version      2.4.0
@description  Increases font size for race prompt with dark purple background
==/UserStyle== */

/* Apply dark purple background and larger text to all prompt layers */
[class*="raceText"], 
[class*="raceText"] *, 
[class^="dash-copy"], 
[class^="dash-copy"] *,
[class*="dash-copy-line"], 
[class*="dash-copy-line"] *,
[class*="dash-copy-word"], 
[class*="dash-copy-word"] *,
[class*="dash-copy-letter"], 
[class*="dash-copy-letter"] * {
  background-color: #1a002b !important;
  background: #1a002b !important;
  color: #e0b3ff !important;
  font-size: 1.2em !important; /* Increased font size */
  border: none !important;
  box-shadow: none !important;
}
